import{_ as t,o,c as a,ag as n}from"./chunks/framework.8tqBsFWt.js";const y=JSON.parse('{"title":"The Talent Siphon","description":"","frontmatter":{"title":"The Talent Siphon","order":5},"headers":[],"relativePath":"about/chapters/05-the-talent-siphon.md","filePath":"about/chapters/05-the-talent-siphon.md"}'),r={name:"about/chapters/05-the-talent-siphon.md"};function i(s,e,l,h,d,u){return o(),a("div",null,[...e[0]||(e[0]=[n('<h3 id="_05-the-talent-siphon" tabindex="-1">05.<br>The Talent Siphon <a class="header-anchor" href="#_05-the-talent-siphon" aria-label="Permalink to &quot;05.&lt;br&gt;The Talent Siphon&quot;">​</a></h3><h4 id="levels-and-ladders" tabindex="-1">Levels and Ladders <a class="header-anchor" href="#levels-and-ladders" aria-label="Permalink to &quot;Levels and Ladders&quot;">​</a></h4><p>My uncle worked for one single firm, leaving school at 15, for more than 50 years. They took him on as a 15-year-old apprentice and educated him over half a century, his loyalty rewarded with a pension and countless friends that would keep him busy in retirement. That romantic image is a postcard from the past that we look back on fondly knowing that it is beyond us and will not return.</p><p>In reality, in a hyper-connected, distributed world, no-one works for a single employer forever anymore. At least not in small companies.</p><p>&#39;Are you telling me I shouldn&#39;t want experienced people to employ and trust for as long as possible?&#39;</p><p>Challenging a &#39;self-evident&#39; truth (or just &#39;common wisdom&#39;) should be considered strange. There are some axioms that make no sense to question, but in a highly volatile marketplace where it&#39;s as easy to go out of business as it is to start one, very little should remain gospel. It&#39;s probable that you&#39;re invested too heavily in both what&#39;s worked for you so far (you made it a decade in business), and what worked for previous generations (see: my uncle).If labor efficiency is the wind that gets us places, the cost and effectiveness of that labor is the size of the sail. Even a gale isn&#39;t going to do much for us if our sail is the size of a napkin.</p><p>Do you want experience? Some. But I need you to realize that 10 years as an Account Manager at 10 different companies is one year of experience multiplied 10 times. It&#39;s not the same as constant growth. And if you hire a different Account Manager with a decade of experience doing good things for another (single) firm, you&#39;re buying them — the complete sum of their experience, good and bad — at a higher cost. It better be highly relevant to what you do <em>and the way you do it</em>.</p><p>Should you hire people for as long as possible? Are they a good cultural fit and highly productive? Are they continuing to add value by solving new mysteries and rising through the Levels in your firm? Great. More likely, they get things done very well and quickly but want no part in your culture. Or the opposite: everyone loves them — <em>how would we ever do without them?</em> — but they have no end product. In either case they are below the standard you need.</p><p>Instead of hoping your best people stay (and do not ask for consistent raises), it&#39;s important to get ahead of the narrative and define what you offer your people when they arrive with hope and energy. Ironically, the more you embrace the reality that some day they will work elsewhere (but that you&#39;re going to give them the finest preparation for the world), the longer they will want to stay with you, to repay the effort you&#39;ve invested in their career (not just <em>this</em> job and what they&#39;re going to do for you).</p><blockquote><p>The more closely you define and help develop and individual&#39;s career, the more likely you are going to have a long-term employee.</p><p>— <em>Simple Numbers. Straight Talk, Big Profits!</em></p></blockquote><p>By investing in people at the level they&#39;re at, you develop a team with high standards. I call this the Talent Siphon. Using four levels to label each employees role and status:</p><ul><li>Designer, Level One (most junior)</li><li>Designer, Level Two</li><li>Designer, Level Three</li><li>Designer, Level Four (most senior)</li></ul><p>Most small firms do not need three Level Four designers, they need a range of skill levels that siphons, or pulls, each level into the next:</p><ul><li>Level Ones grow to become Level Twos</li><li>Level Twos grow to become Level Threes</li><li>Level Threes grow to become Level Fours</li></ul><p>By taking this approach you can set both the skills required for each level, and the accompanying salary range, based <em>on your needs!</em> Not the industry&#39;s needs, on yours.</p><h5 id="what-happens-when-level-fours-max-out-your-salary-range" tabindex="-1">What Happens When Level Fours Max Out Your Salary Range? <a class="header-anchor" href="#what-happens-when-level-fours-max-out-your-salary-range" aria-label="Permalink to &quot;What Happens When Level Fours Max Out Your Salary Range?&quot;">​</a></h5><p>You have an adult conversation and remind them of what you can afford, and the numerous non-monetary advantages of working for a small firm like yours. People are going to find more money elsewhere, both because bigger businesses with equally big ambitions need Staff Designers, but because your competitors will over-pay (based on market standards) your people, risking financial peril, all because they cannot find and teach Level One prospects. They cannot develop talent, which is why it becomes your winning advantage.</p>',17)])])}const c=t(r,[["render",i]]);export{y as __pageData,c as default};
